#!/bin/sh
# Prepare Garage for the LMS (admin API v2). Idempotent: runs on every deploy and exits 0.
#   1. assign the single node a role in the cluster layout (a fresh node stores nothing until then)
#   2. import the API's access key (generated by gen-stack-env.sh, so it lives in stack.env)
#   3. create the bucket and give the key read/write on it
set -eu

: "${GARAGE_ADMIN_TOKEN:?}" "${S3_ACCESS_KEY_ID:?}" "${S3_SECRET_ACCESS_KEY:?}" "${S3_BUCKET:?}"
ADMIN="${GARAGE_ADMIN_URL:-http://garage:3903}"
CAPACITY_GB="${STORAGE_CAPACITY_GB:-100}"

api() { # METHOD PATH [JSON]
  if [ $# -ge 3 ]; then
    curl -fsS -X "$1" -H "Authorization: Bearer $GARAGE_ADMIN_TOKEN" \
      -H 'Content-Type: application/json' -d "$3" "$ADMIN$2"
  else
    curl -fsS -X "$1" -H "Authorization: Bearer $GARAGE_ADMIN_TOKEN" "$ADMIN$2"
  fi
}

echo "waiting for Garage at $ADMIN"
i=0
until status=$(api GET /v2/GetClusterStatus 2>/dev/null); do
  i=$((i + 1)); [ "$i" -le 60 ] || { echo "Garage did not answer"; exit 1; }
  sleep 2
done

layout=$(api GET /v2/GetClusterLayout)
if [ "$(echo "$layout" | jq '.roles | length')" -eq 0 ]; then
  node=$(echo "$status" | jq -r '.nodes[0].id')
  version=$(echo "$layout" | jq '.version')
  api POST /v2/UpdateClusterLayout \
    "{\"roles\":[{\"id\":\"$node\",\"zone\":\"home\",\"capacity\":$((CAPACITY_GB * 1000000000)),\"tags\":[]}]}" >/dev/null
  api POST /v2/ApplyClusterLayout "{\"version\":$((version + 1))}" >/dev/null
  echo "layout: node $(echo "$node" | cut -c1-16) assigned ${CAPACITY_GB} GB"
else
  echo "layout: already assigned"
fi

if api GET "/v2/GetKeyInfo?id=$S3_ACCESS_KEY_ID" >/dev/null 2>&1; then
  echo "key: $S3_ACCESS_KEY_ID exists"
else
  api POST /v2/ImportKey \
    "{\"accessKeyId\":\"$S3_ACCESS_KEY_ID\",\"secretAccessKey\":\"$S3_SECRET_ACCESS_KEY\",\"name\":\"lms-api\"}" >/dev/null
  echo "key: $S3_ACCESS_KEY_ID imported"
fi

if bucket=$(api GET "/v2/GetBucketInfo?globalAlias=$S3_BUCKET" 2>/dev/null); then
  echo "bucket: $S3_BUCKET exists"
else
  bucket=$(api POST /v2/CreateBucket "{\"globalAlias\":\"$S3_BUCKET\"}")
  echo "bucket: $S3_BUCKET created"
fi
bucket_id=$(echo "$bucket" | jq -r '.id')

api POST /v2/AllowBucketKey \
  "{\"bucketId\":\"$bucket_id\",\"accessKeyId\":\"$S3_ACCESS_KEY_ID\",\"permissions\":{\"read\":true,\"write\":true,\"owner\":false}}" >/dev/null
echo "bucket: key can read and write. Done."
